import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.BfsW3bkh.js";var i=JSON.parse(`{"title":"LowRank reconstruction","description":"","frontmatter":{},"headers":[],"relativePath":"guide/low-rank.md","filePath":"guide/low-rank.md","lastUpdated":0}`),a={name:`guide/low-rank.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="lowrank-reconstruction" tabindex="-1">LowRank reconstruction <a class="header-anchor" href="#lowrank-reconstruction" aria-label="Permalink to “LowRank reconstruction”">​</a></h1><p><code>HighOrderLowRankOp</code> retains the first-order Fourier terms in an NFFT and approximates the residual phase using temporal and spatial factors. Choose how the factors are constructed with <code>method</code>; choose their execution separately.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Method</th><th style="text-align:left;">Construction</th><th style="text-align:left;">Strategy</th><th style="text-align:left;">Detail</th></tr></thead><tbody><tr><td style="text-align:left;"><code>:per_readout</code></td><td style="text-align:left;">Independent local rSVD factors</td><td style="text-align:left;">—</td><td style="text-align:left;"><a href="/HighOrderMRI.jl/dev/guide/per-readout">Per-readout</a></td></tr><tr><td style="text-align:left;"><code>:incremental_shared</code></td><td style="text-align:left;">Local rSVD followed by incremental spatial compression</td><td style="text-align:left;">—</td><td style="text-align:left;"><a href="/HighOrderMRI.jl/dev/guide/incremental-shared">Incremental Shared</a></td></tr><tr><td style="text-align:left;"><code>:direct_shared</code></td><td style="text-align:left;">Representative phase snapshots directly form a shared parent</td><td style="text-align:left;"><code>:per_readout</code> or <code>:global</code></td><td style="text-align:left;"><a href="/HighOrderMRI.jl/dev/guide/direct-shared">Direct Shared</a></td></tr></tbody></table><p>The default <code>method=:incremental_shared</code> selects Incremental Shared. Omitting <code>strategy</code> with <code>method=:direct_shared</code> selects its Per-readout strategy. <code>strategy</code> is otherwise unset and only valid with Direct Shared.</p><p><code>method=:per_readout</code> keeps independent factors. <code>method=:direct_shared, strategy=:per_readout</code> still uses one shared spatial basis; Per-readout here specifies its rank-selection and checking strategy.</p><h2 id="input-and-numerical-representation" tabindex="-1">Input and numerical representation <a class="header-anchor" href="#input-and-numerical-representation" aria-label="Permalink to “Input and numerical representation”">​</a></h2><p>Coefficients are <code>(nTerm,nSam,nDyn)</code> and times are <code>(nSam,nDyn)</code>. The convenience constructor accepts one coefficient matrix and time vector. Every readout encodes the same unknown full-grid image. Samples vary fastest, then readouts, then coils. For <code>recon_HOOp</code>, reshape data to <code>(nSam*nDyn,nCha)</code>.</p><p>The pure residual factors exclude the zeroth-order temporal phase, first-order NFFT, CSM, weights and voxel normalization. The operator folds the required temporal corrections and normalization once. In 2D, <code>kz*z</code> remains a residual term. See the <a href="/HighOrderMRI.jl/dev/theory/encoding-model">encoding model</a> for coordinate scope.</p><h2 id="construction-and-execution-are-separate" tabindex="-1">Construction and execution are separate <a class="header-anchor" href="#construction-and-execution-are-separate" aria-label="Permalink to “Construction and execution are separate”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Setting</th><th style="text-align:left;">Role</th></tr></thead><tbody><tr><td style="text-align:left;"><code>method</code>, <code>strategy</code></td><td style="text-align:left;">Construct and select factors</td></tr><tr><td style="text-align:left;"><code>rsvd_distribution</code></td><td style="text-align:left;">Execute local rSVD setup; Direct Shared uses the primary device</td></tr><tr><td style="text-align:left;"><code>per_readout_storage</code></td><td style="text-align:left;">Resident, CPU-streamed or regenerated independent factors</td></tr><tr><td style="text-align:left;"><code>normal_distribution</code></td><td style="text-align:left;">Assign solver work to one device, coil groups, readout groups or rank groups</td></tr><tr><td style="text-align:left;"><code>normal_method</code></td><td style="text-align:left;">Standard or supported batched CUDA execution</td></tr><tr><td style="text-align:left;"><code>normal_options</code></td><td style="text-align:left;">Existing opt-in execution resources, including pruned FFT</td></tr></tbody></table><p>Defaults remain CPU arrays, single-device standard execution and unchanged NUFFT settings. Batched/pruned execution does not become enabled by selecting a new method name. Per-readout, Incremental Shared and Direct Shared can have different storage and distribution restrictions; use the <a href="/HighOrderMRI.jl/dev/reference/highorderlowrankop#choose-setup-and-reconstruction-execution-separately">execution reference</a> and <a href="/HighOrderMRI.jl/dev/guide/multi-gpu">multi-GPU guide</a>.</p><h2 id="construction-controls" tabindex="-1">Construction controls <a class="header-anchor" href="#construction-controls" aria-label="Permalink to “Construction controls”">​</a></h2><p>Use <code>method</code> and <code>strategy</code> to select the algorithm. <code>joint_*</code> options tune Direct Shared&#39;s Per-readout strategy; <code>adaptive_options</code> configures Global. These controls retain their numerical meanings. See the <a href="/HighOrderMRI.jl/dev/reference/highorderlowrankop">complete API</a> and <a href="/HighOrderMRI.jl/dev/guide/validation">validation guide</a>.</p>`,13)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};